// ── Only ever return a connected/not-connected flag plus non-secret fields ──
// The frontend must never see a stored apiKey or appPassword again after it's saved.
// WordPress supports multiple sites: each is its own row keyed "wordpress:<id>".
const rows = $input.all();

function parseData(row) {
  try { return JSON.parse(row.json.data || '{}'); } catch (e) { return null; }
}

const brevoRow = rows.find(r => (r.json.service || '').toLowerCase() === 'brevo');
const brevoData = brevoRow ? parseData(brevoRow) : null;

const wordpressSites = rows
  .filter(r => (r.json.service || '').toLowerCase().startsWith('wordpress:'))
  .map(r => parseData(r))
  .filter(d => d && d.siteUrl && d.username && d.appPassword)
  .map(d => ({ id: d.id, label: d.label || d.siteUrl, siteUrl: d.siteUrl, username: d.username }));

return [{
  json: {
    brevo: {
      connected: !!(brevoData && brevoData.apiKey),
      listId: (brevoData && brevoData.listId) || ''
    },
    wordpressSites
  }
}];
